package com.birdhouse.tracker;

/** Detects material wall-clock discontinuities while the client is running. */
final class BirdhouseClockGuard
{
    static final long DISCONTINUITY_TOLERANCE_SECONDS = 120L;

    private long previousWallSeconds = Long.MIN_VALUE;
    private long previousMonotonicNanos = Long.MIN_VALUE;

    boolean observe(long wallSeconds, long monotonicNanos)
    {
        if (previousWallSeconds == Long.MIN_VALUE || previousMonotonicNanos == Long.MIN_VALUE)
        {
            previousWallSeconds = wallSeconds;
            previousMonotonicNanos = monotonicNanos;
            return false;
        }

        long wallElapsed = wallSeconds - previousWallSeconds;
        long monotonicElapsed = Math.max(0L, (monotonicNanos - previousMonotonicNanos) / 1_000_000_000L);
        long difference = Math.abs(wallElapsed - monotonicElapsed);
        previousWallSeconds = wallSeconds;
        previousMonotonicNanos = monotonicNanos;
        return difference > DISCONTINUITY_TOLERANCE_SECONDS;
    }

    void reset()
    {
        previousWallSeconds = Long.MIN_VALUE;
        previousMonotonicNanos = Long.MIN_VALUE;
    }
}

package com.birdhouse.tracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Polygon;
import java.awt.Rectangle;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/** Compact inline amber warning triangle and label for the existing RuneLite overlay. */
final class BirdhouseDependencyWarningComponent implements LayoutableRenderableEntity
{
    static final String LABEL = "Time Tracking Disabled";
    static final Color ICON_COLOR = new Color(255, 190, 75);
    private static final Color ICON_MARK_COLOR = new Color(55, 43, 22);
    private static final Color TEXT_COLOR = Color.WHITE;
    private static final int ICON_SIZE = 11;
    private static final int GAP = 5;

    private final Rectangle bounds = new Rectangle();
    private Point preferredLocation = new Point();

    @Override
    public Dimension render(Graphics2D graphics)
    {
        FontMetrics metrics = graphics.getFontMetrics();
        int height = Math.max(metrics.getHeight(), ICON_SIZE);
        int iconX = preferredLocation.x;
        int iconY = preferredLocation.y + (height - ICON_SIZE) / 2;
        int centerX = iconX + ICON_SIZE / 2;

        Polygon triangle = new Polygon(
            new int[] {iconX, centerX, iconX + ICON_SIZE},
            new int[] {iconY + ICON_SIZE, iconY, iconY + ICON_SIZE}, 3);

        Color oldColor = graphics.getColor();
        graphics.setColor(ICON_COLOR);
        graphics.fillPolygon(triangle);
        graphics.setColor(ICON_MARK_COLOR);
        graphics.drawLine(centerX, iconY + 3, centerX, iconY + 7);
        graphics.fillOval(centerX - 1, iconY + 8, 2, 2);
        graphics.setColor(TEXT_COLOR);
        graphics.drawString(LABEL, iconX + ICON_SIZE + GAP,
            preferredLocation.y + metrics.getAscent());
        graphics.setColor(oldColor);

        int width = ICON_SIZE + GAP + metrics.stringWidth(LABEL);
        bounds.setBounds(preferredLocation.x, preferredLocation.y, width, height);
        return new Dimension(width, height);
    }

    @Override
    public Rectangle getBounds()
    {
        return bounds;
    }

    @Override
    public void setPreferredLocation(Point position)
    {
        preferredLocation = position == null ? new Point() : new Point(position);
    }

    @Override
    public void setPreferredSize(Dimension dimension)
    {
        // Width is determined by the RuneLite font metrics and compact icon.
    }
}

package com.birdhouse.tracker;

/** Pure decision rule for a group's estimated READY deadline. */
final class BirdhouseGroupDeadlinePolicy
{
    enum Action
    {
        WAIT,
        DISPATCH,
        SKIP
    }

    private BirdhouseGroupDeadlinePolicy()
    {
    }

    static Action evaluate(BirdhousePlantingGroup group, long effectiveNow,
        boolean newlyDiscovered, boolean reconciliationBoundary, boolean clockDiscontinuity,
        long wallNow)
    {
        if (group == null || !group.isPending() || group.deadline() > effectiveNow)
        {
            return Action.WAIT;
        }

        // A deadline first observed as overdue is never caught up. This includes
        // startup after RuneLite was closed, Time Tracking reactivation, and
        // material wall-clock changes while the client was running.
        if (newlyDiscovered || reconciliationBoundary || clockDiscontinuity
            || wallNow < effectiveNow)
        {
            return Action.SKIP;
        }

        return Action.DISPATCH;
    }
}

package com.birdhouse.tracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** Reconciles persisted pending groups with currently valid seeded Time Tracking records. */
final class BirdhouseGroupReconciler
{
    private BirdhouseGroupReconciler()
    {
    }

    static Result reconcile(List<BirdhousePlantingGroup> storedGroups,
        List<BirdhouseTimer> currentTimers, long nowSeconds)
    {
        List<BirdhousePlantingGroup> groups = new ArrayList<>();
        List<BirdhousePlantingGroup> terminal = new ArrayList<>();
        Set<String> knownCycles = new HashSet<>();

        for (BirdhousePlantingGroup stored : safe(storedGroups))
        {
            if (stored.status != BirdhousePlantingGroup.Status.PENDING)
            {
                terminal.add(stored);
                knownCycles.addAll(stored.cycleKeys);
                continue;
            }

            List<String> retained = new ArrayList<>();
            boolean hasCurrentMember = false;
            for (String cycle : stored.cycleKeys)
            {
                long plantedAt = BirdhousePlantingGroup.plantedAt(cycle);
                int varp = BirdhousePlantingGroup.siteVarp(cycle);
                String currentForSite = currentCycleForSite(currentTimers, varp);
                // A matured cycle remains part of its original group while at least
                // one member of that group is still represented by the current saved
                // Time Tracking record. This preserves the group's latest deadline
                // after an earlier mature member is harvested. If every member has
                // been removed/replaced, the old group is finished locally and must
                // not emit a stale READY reminder after the player already serviced it.
                if (cycle.equals(currentForSite))
                {
                    retained.add(cycle);
                    hasCurrentMember = true;
                }
                else if (plantedAt != Long.MIN_VALUE
                    && plantedAt + BirdhouseTimer.MATURITY_SECONDS <= nowSeconds)
                {
                    retained.add(cycle);
                }
            }

            if (!hasCurrentMember && stored.deadline() > nowSeconds)
            {
                // No currently visible member is not sufficient evidence that every
                // cycle was harvested or replaced. In particular, Time Tracking can
                // provide an empty or incomplete snapshot temporarily. Preserve the
                // original pending group and its cycle identities until the latest
                // member's estimated maturity deadline; if the records return before
                // then, they can reconcile to this same group. Once the group deadline
                // is due, the existing no-catch-up policy below marks it SKIPPED.
                groups.add(stored);
                knownCycles.addAll(stored.cycleKeys);
            }
            else if (retained.isEmpty() || !hasCurrentMember)
            {
                terminal.add(stored.terminal(BirdhousePlantingGroup.Status.SKIPPED));
                knownCycles.addAll(stored.cycleKeys);
            }
            else
            {
                BirdhousePlantingGroup normalized = retained.size() == stored.cycleKeys.size()
                    ? stored : stored.withMembers(retained);
                groups.add(normalized);
                knownCycles.addAll(normalized.cycleKeys);
            }
        }

        List<BirdhouseTimer> newTimers = new ArrayList<>();
        for (BirdhouseTimer timer : safe(currentTimers))
        {
            if (!knownCycles.contains(timer.cycleKey))
            {
                newTimers.add(timer);
            }
        }

        // A graph node is one persisted pending group or one newly observed cycle.
        // Nodes join when any member pair is within the consecutive five-minute rule.
        List<Node> nodes = new ArrayList<>();
        for (BirdhousePlantingGroup group : groups)
        {
            nodes.add(Node.forGroup(group));
        }
        for (BirdhouseTimer timer : newTimers)
        {
            nodes.add(Node.forTimer(timer));
        }

        UnionFind union = new UnionFind(nodes.size());
        for (int left = 0; left < nodes.size(); left++)
        {
            for (int right = left + 1; right < nodes.size(); right++)
            {
                if (nodes.get(left).isAdjacent(nodes.get(right)))
                {
                    union.join(left, right);
                }
            }
        }

        List<BirdhousePlantingGroup> reconciled = new ArrayList<>(terminal);
        Set<String> newlyObservedGroupIds = new LinkedHashSet<>();
        boolean[] processed = new boolean[nodes.size()];
        for (int i = 0; i < nodes.size(); i++)
        {
            if (processed[i])
            {
                continue;
            }
            int root = union.find(i);
            List<BirdhousePlantingGroup> componentGroups = new ArrayList<>();
            List<BirdhouseTimer> componentTimers = new ArrayList<>();
            for (int j = i; j < nodes.size(); j++)
            {
                if (union.find(j) != root)
                {
                    continue;
                }
                processed[j] = true;
                Node node = nodes.get(j);
                if (node.group != null)
                {
                    componentGroups.add(node.group);
                }
                else
                {
                    componentTimers.add(node.timer);
                }
            }

            if (componentGroups.isEmpty())
            {
                BirdhousePlantingGroup created = BirdhousePlantingGroup.create(componentTimers, nowSeconds);
                reconciled.add(created);
                newlyObservedGroupIds.add(created.id);
                continue;
            }

            componentGroups.sort(Comparator.comparingLong(BirdhousePlantingGroup::firstPlantedAt)
                .thenComparing(group -> group.id));
            BirdhousePlantingGroup canonical = componentGroups.get(0);
            Set<String> members = new LinkedHashSet<>();
            for (BirdhousePlantingGroup group : componentGroups)
            {
                members.addAll(group.cycleKeys);
            }
            for (BirdhouseTimer timer : componentTimers)
            {
                members.add(timer.cycleKey);
            }
            reconciled.add(canonical.withMembers(members));
            if (!componentTimers.isEmpty())
            {
                // A newly observed cycle can extend an existing pending group.
                // If that group's revised deadline is already overdue, it must be
                // skipped rather than dispatched as a catch-up notification.
                newlyObservedGroupIds.add(canonical.id);
            }
        }

        reconciled.sort(Comparator.comparingLong(BirdhousePlantingGroup::firstPlantedAt)
            .thenComparing(group -> group.id));
        return new Result(reconciled, newlyObservedGroupIds);
    }

    /** Mark estimated deadlines missed at startup/outage boundaries without replay. */
    static List<BirdhousePlantingGroup> skipOverdue(List<BirdhousePlantingGroup> groups, long nowSeconds)
    {
        List<BirdhousePlantingGroup> result = new ArrayList<>();
        for (BirdhousePlantingGroup group : safe(groups))
        {
            if (group.isPending() && group.deadline() <= nowSeconds)
            {
                result.add(group.terminal(BirdhousePlantingGroup.Status.SKIPPED));
            }
            else
            {
                result.add(group);
            }
        }
        return Collections.unmodifiableList(result);
    }

    private static String currentCycleForSite(List<BirdhouseTimer> timers, int varp)
    {
        for (BirdhouseTimer timer : safe(timers))
        {
            if (timer.site.varp == varp)
            {
                return timer.cycleKey;
            }
        }
        return null;
    }

    private static <T> List<T> safe(List<T> values)
    {
        return values == null ? Collections.<T>emptyList() : values;
    }

    static final class Result
    {
        final List<BirdhousePlantingGroup> groups;
        final Set<String> newlyObservedGroupIds;

        private Result(List<BirdhousePlantingGroup> groups, Set<String> newlyObservedGroupIds)
        {
            this.groups = Collections.unmodifiableList(new ArrayList<>(groups));
            this.newlyObservedGroupIds = Collections.unmodifiableSet(new HashSet<>(newlyObservedGroupIds));
        }
    }

    private static final class Node
    {
        final BirdhousePlantingGroup group;
        final BirdhouseTimer timer;
        final List<String> cycles;

        private Node(BirdhousePlantingGroup group, BirdhouseTimer timer, List<String> cycles)
        {
            this.group = group;
            this.timer = timer;
            this.cycles = cycles;
        }

        static Node forGroup(BirdhousePlantingGroup group)
        {
            return new Node(group, null, group.cycleKeys);
        }

        static Node forTimer(BirdhouseTimer timer)
        {
            return new Node(null, timer, Collections.singletonList(timer.cycleKey));
        }

        boolean isAdjacent(Node other)
        {
            for (String left : cycles)
            {
                long leftTime = BirdhousePlantingGroup.plantedAt(left);
                for (String right : other.cycles)
                {
                    long rightTime = BirdhousePlantingGroup.plantedAt(right);
                    if (leftTime != Long.MIN_VALUE && rightTime != Long.MIN_VALUE
                        && BirdhousePlantingGroup.cyclesAreAdjacent(leftTime, rightTime))
                    {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    private static final class UnionFind
    {
        private final int[] parent;
        private final byte[] rank;

        private UnionFind(int size)
        {
            parent = new int[size];
            rank = new byte[size];
            for (int i = 0; i < size; i++)
            {
                parent[i] = i;
            }
        }

        int find(int value)
        {
            if (parent[value] != value)
            {
                parent[value] = find(parent[value]);
            }
            return parent[value];
        }

        void join(int left, int right)
        {
            int leftRoot = find(left);
            int rightRoot = find(right);
            if (leftRoot == rightRoot)
            {
                return;
            }
            if (rank[leftRoot] < rank[rightRoot])
            {
                parent[leftRoot] = rightRoot;
            }
            else if (rank[leftRoot] > rank[rightRoot])
            {
                parent[rightRoot] = leftRoot;
            }
            else
            {
                parent[rightRoot] = leftRoot;
                rank[leftRoot]++;
            }
        }
    }
}

package com.birdhouse.tracker;

import java.awt.Color;
import java.awt.TrayIcon;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.FlashNotification;
import net.runelite.client.config.Notification;
import net.runelite.client.config.NotificationSound;
import net.runelite.client.config.RequestFocusType;
import net.runelite.client.config.RuneLiteConfig;

/** READY delivery channels, shared by live events and founder-only smoke tests. */
final class BirdhouseNotificationDelivery
{
    static final Color CHAT_RED = new Color(255, 0, 0);
    static final String TIME_TRACKING_DISABLED_TEXT =
        "Birdhouse Timer: Time Tracking is disabled. Enable it in RuneLite Configuration > search \"Time Tracking\" > enable.";
    // Explicitly desktop-only to avoid the second, default-highlight chat message
    // that RuneLite's generic notifier can otherwise generate.
    private final ChatMessageManager chatMessageManager;
    private final Notifier notifier;
    private final RuneLiteConfig runeLiteConfig;

    @Inject
    BirdhouseNotificationDelivery(ChatMessageManager chatMessageManager, Notifier notifier,
        RuneLiteConfig runeLiteConfig)
    {
        this.chatMessageManager = chatMessageManager;
        this.notifier = notifier;
        this.runeLiteConfig = runeLiteConfig;
    }

    void sendReady(boolean redChatEnabled, boolean desktopEnabled)
    {
        dispatchReady(redChatEnabled, desktopEnabled, this::sendRedChat, this::sendDesktop);
    }

    /** Independent per-player READY choices; production and tests share this branch. */
    static void dispatchReady(boolean redChatEnabled, boolean desktopEnabled,
        Runnable redChat, Runnable desktop)
    {
        if (redChatEnabled)
        {
            try
            {
                redChat.run();
            }
            finally
            {
                // A chat failure must not prevent an enabled desktop attempt.
                if (desktopEnabled)
                {
                    desktop.run();
                }
            }
        }
        else if (desktopEnabled)
        {
            desktop.run();
        }
    }

    void sendRedChat()
    {
        String formatted = new ChatMessageBuilder()
            .append(CHAT_RED, BirdhouseWarningMessage.READY_TEXT)
            .build();
        chatMessageManager.queue(QueuedMessage.builder()
            .type(ChatMessageType.CONSOLE)
            .runeLiteFormattedMessage(formatted)
            .build());
    }

    void sendDesktop()
    {
        // Notifier only applies RuneLite's global focus rule when this per-notification
        // flag is false and the client is focused. Read the global preference at the
        // moment of delivery so user changes take effect without restarting the plugin.
        notifier.notify(desktopNotification(runeLiteConfig.sendNotificationsWhenFocused()),
            BirdhouseWarningMessage.READY_TEXT);
    }

    /** Desktop-only notification that follows RuneLite's global focus preference. */
    static Notification desktopNotification(boolean sendWhenFocused)
    {
        return new Notification(
            true, true, true, true, TrayIcon.MessageType.INFO,
            RequestFocusType.OFF, NotificationSound.OFF, null, 0, 0,
            false, FlashNotification.DISABLED, CHAT_RED, sendWhenFocused);
    }

    /** A dependency warning is not a READY alert and is independent of READY preferences. */
    void sendTimeTrackingDisabledWarning()
    {
        String formatted = new ChatMessageBuilder()
            .append(CHAT_RED, TIME_TRACKING_DISABLED_TEXT)
            .build();
        chatMessageManager.queue(QueuedMessage.builder()
            .type(ChatMessageType.CONSOLE)
            .runeLiteFormattedMessage(formatted)
            .build());
    }
}

package com.birdhouse.tracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** Movable game-screen overlay for active sites, with an explicit empty state. */
final class BirdhouseOverlay extends OverlayPanel
{
    static final int COMPACT_WIDTH_PX = 190;
    static final String EMPTY_STATE_MESSAGE = "No active birdhouses";
    static final String TITLE = "Birdhouse Timers";
    static final String TIME_TRACKING_INSTRUCTION_1 = "1. Open Configuration (wrench)";
    static final String TIME_TRACKING_INSTRUCTION_2 = "2. Search Time Tracking";
    static final String TIME_TRACKING_INSTRUCTION_3 = "3. Enable Time Tracking";
    static final Color READY_COLOR = new Color(0, 255, 0); // Bright green to match RuneLite Farming READY text.
    static final Color SOON_COLOR = new Color(255, 220, 50);
    static final Color GROWING_COLOR = new Color(255, 80, 80);
    static final Color DEPENDENCY_WARNING_COLOR = new Color(255, 190, 75);

    private final BirdhouseTrackerPlugin plugin;
    private final BirdhouseTrackerConfig config;

    @Inject
    BirdhouseOverlay(BirdhouseTrackerPlugin plugin, BirdhouseTrackerConfig config)
    {
        super(plugin);
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setPriority(PRIORITY_MED);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        List<BirdhouseTimer> timers = plugin.getTimers();
        panelComponent.setPreferredSize(new Dimension(COMPACT_WIDTH_PX, 0));
        panelComponent.getChildren().add(TitleComponent.builder()
            .text(TITLE)
            .build());

        boolean dependencyWarning = TimeTrackingDependencyStatus.shouldShowOverlayWarning(
            plugin.isTimeTrackingStatusKnownForOverlay(), plugin.isTimeTrackingActiveForOverlay());
        if (dependencyWarning)
        {
            panelComponent.getChildren().add(new BirdhouseDependencyWarningComponent());
            panelComponent.getChildren().add(LineComponent.builder()
                .left("To enable:")
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left(TIME_TRACKING_INSTRUCTION_1)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left(TIME_TRACKING_INSTRUCTION_2)
                .build());
            panelComponent.getChildren().add(LineComponent.builder()
                .left(TIME_TRACKING_INSTRUCTION_3)
                .build());
        }

        if (shouldShowEmptyState(timers.isEmpty(), dependencyWarning))
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left(EMPTY_STATE_MESSAGE)
                .build());
            return super.render(graphics);
        }
        if (timers.isEmpty())
        {
            // A dependency warning already explains why no current timers are shown.
            return super.render(graphics);
        }

        long now = Instant.now().getEpochSecond();
        for (BirdhouseTimer timer : timers)
        {
            long remaining = timer.secondsRemaining(now);
            Color statusColor = statusColor(remaining, config.warningLeadTime());
            String label = timer.site.displayLabel();
            panelComponent.getChildren().add(LineComponent.builder()
                .left(label)
                .leftColor(Color.WHITE)
                .right(timer.display(now))
                .rightColor(statusColor)
                .build());
        }
        return super.render(graphics);
    }

    static boolean shouldShowEmptyState(boolean timersEmpty, boolean dependencyWarning)
    {
        return timersEmpty && !dependencyWarning;
    }

    /** The existing advance-warning preference also controls the yellow visual cue. */
    static Color statusColor(long remainingSeconds, WarningLeadTime leadTime)
    {
        if (remainingSeconds <= 0)
        {
            // READY denotes the 50-minute estimate, not confirmed maturity.
            return READY_COLOR;
        }
        int warningMinutes = leadTime == null ? 0 : leadTime.minutes;
        return warningMinutes > 0 && remainingSeconds <= warningMinutes * 60L
            ? SOON_COLOR : GROWING_COLOR;
    }
}

package com.birdhouse.tracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Persistent notification group for planting cycles connected by consecutive
 * planting gaps of at most five minutes. Group membership is distinct from the
 * current set of visible timers and is never inferred from event arrival order.
 */
final class BirdhousePlantingGroup
{
    static final long MAX_CONSECUTIVE_GAP_SECONDS = 5 * 60L;
    static final String SERIAL_VERSION = "1";

    enum Status
    {
        PENDING,
        DISPATCHED,
        SKIPPED
    }

    enum ChannelOutcome
    {
        NOT_ATTEMPTED,
        ATTEMPTING,
        ATTEMPTED,
        DISABLED,
        FAILED
    }

    final String id;
    final List<String> cycleKeys;
    final long createdAt;
    final Status status;
    final ChannelOutcome chatOutcome;
    final ChannelOutcome desktopOutcome;

    private BirdhousePlantingGroup(String id, List<String> cycleKeys, long createdAt,
        Status status, ChannelOutcome chatOutcome, ChannelOutcome desktopOutcome)
    {
        if (id == null || id.trim().isEmpty())
        {
            throw new IllegalArgumentException("Group ID is required");
        }
        if (cycleKeys == null || cycleKeys.isEmpty())
        {
            throw new IllegalArgumentException("A group must contain at least one planting cycle");
        }
        this.id = id;
        List<String> sorted = new ArrayList<>(new LinkedHashSet<>(cycleKeys));
        sorted.sort(Comparator.comparingLong(BirdhousePlantingGroup::plantedAt)
            .thenComparingInt(BirdhousePlantingGroup::siteVarp));
        this.cycleKeys = Collections.unmodifiableList(sorted);
        this.createdAt = createdAt;
        this.status = status;
        this.chatOutcome = chatOutcome;
        this.desktopOutcome = desktopOutcome;
    }

    static BirdhousePlantingGroup create(List<BirdhouseTimer> timers, long createdAt)
    {
        if (timers == null || timers.isEmpty())
        {
            throw new IllegalArgumentException("At least one timer is required");
        }
        List<BirdhouseTimer> sorted = new ArrayList<>(timers);
        sorted.sort(Comparator.comparingLong((BirdhouseTimer timer) -> timer.plantedAt)
            .thenComparingInt(timer -> timer.site.varp));
        String id = sorted.get(0).cycleKey;
        List<String> keys = new ArrayList<>();
        for (BirdhouseTimer timer : sorted)
        {
            keys.add(timer.cycleKey);
        }
        return new BirdhousePlantingGroup(id, keys, createdAt, Status.PENDING,
            ChannelOutcome.NOT_ATTEMPTED, ChannelOutcome.NOT_ATTEMPTED);
    }

    static BirdhousePlantingGroup restore(String id, String value)
    {
        if (id == null || value == null)
        {
            return null;
        }
        String[] parts = value.split("\\|", -1);
        if (parts.length != 6 || !SERIAL_VERSION.equals(parts[0]))
        {
            return null;
        }
        try
        {
            long createdAt = Long.parseLong(parts[1]);
            Status status = Status.valueOf(parts[2]);
            ChannelOutcome chat = ChannelOutcome.valueOf(parts[3]);
            ChannelOutcome desktop = ChannelOutcome.valueOf(parts[4]);
            List<String> members = new ArrayList<>();
            if (!parts[5].isEmpty())
            {
                Collections.addAll(members, parts[5].split(",", -1));
            }
            return new BirdhousePlantingGroup(id, members, createdAt, status, chat, desktop);
        }
        catch (IllegalArgumentException ex)
        {
            return null;
        }
    }

    String serialize()
    {
        return SERIAL_VERSION + "|" + createdAt + "|" + status.name() + "|"
            + chatOutcome.name() + "|" + desktopOutcome.name() + "|"
            + String.join(",", cycleKeys);
    }

    long firstPlantedAt()
    {
        return plantedAt(cycleKeys.get(0));
    }

    long latestPlantedAt()
    {
        return plantedAt(cycleKeys.get(cycleKeys.size() - 1));
    }

    long deadline()
    {
        return latestPlantedAt() + BirdhouseTimer.MATURITY_SECONDS;
    }

    boolean contains(String cycleKey)
    {
        return cycleKeys.contains(cycleKey);
    }

    boolean isPending()
    {
        return status == Status.PENDING;
    }

    BirdhousePlantingGroup withMembers(Set<String> members)
    {
        if (!isPending())
        {
            throw new IllegalStateException("Terminal group membership is immutable");
        }
        return new BirdhousePlantingGroup(id, new ArrayList<>(members), createdAt, status,
            chatOutcome, desktopOutcome);
    }

    BirdhousePlantingGroup withMembers(List<String> members)
    {
        if (!isPending())
        {
            throw new IllegalStateException("Terminal group membership is immutable");
        }
        return new BirdhousePlantingGroup(id, members, createdAt, status,
            chatOutcome, desktopOutcome);
    }

    BirdhousePlantingGroup withId(String newId)
    {
        if (!isPending())
        {
            throw new IllegalStateException("Terminal group identity is immutable");
        }
        return new BirdhousePlantingGroup(newId, cycleKeys, createdAt, status,
            chatOutcome, desktopOutcome);
    }

    BirdhousePlantingGroup terminal(Status newStatus)
    {
        if (newStatus == Status.PENDING)
        {
            throw new IllegalArgumentException("Terminal state is required");
        }
        if (!isPending())
        {
            return this;
        }
        return new BirdhousePlantingGroup(id, cycleKeys, createdAt, newStatus,
            chatOutcome, desktopOutcome);
    }

    BirdhousePlantingGroup withChatOutcome(ChannelOutcome outcome)
    {
        return new BirdhousePlantingGroup(id, cycleKeys, createdAt, status,
            outcome, desktopOutcome);
    }

    BirdhousePlantingGroup withDesktopOutcome(ChannelOutcome outcome)
    {
        return new BirdhousePlantingGroup(id, cycleKeys, createdAt, status,
            chatOutcome, outcome);
    }

    static String encodeConfigKey(String id)
    {
        return java.util.Base64.getUrlEncoder().withoutPadding()
            .encodeToString(id.getBytes(java.nio.charset.StandardCharsets.UTF_8));
    }

    static String decodeConfigKey(String encoded)
    {
        try
        {
            return new String(java.util.Base64.getUrlDecoder().decode(encoded),
                java.nio.charset.StandardCharsets.UTF_8);
        }
        catch (IllegalArgumentException ex)
        {
            return null;
        }
    }

    static int siteVarp(String cycleKey)
    {
        if (cycleKey == null)
        {
            return -1;
        }
        int separator = cycleKey.indexOf(':');
        if (separator <= 0)
        {
            return -1;
        }
        try
        {
            return Integer.parseInt(cycleKey.substring(0, separator));
        }
        catch (NumberFormatException ex)
        {
            return -1;
        }
    }

    static long plantedAt(String cycleKey)
    {
        if (cycleKey == null)
        {
            return Long.MIN_VALUE;
        }
        int first = cycleKey.indexOf(':');
        int last = cycleKey.lastIndexOf(':');
        if (first < 0 || last <= first || last == cycleKey.length() - 1)
        {
            return Long.MIN_VALUE;
        }
        try
        {
            return Long.parseLong(cycleKey.substring(last + 1));
        }
        catch (NumberFormatException ex)
        {
            return Long.MIN_VALUE;
        }
    }

    static boolean cyclesAreAdjacent(long left, long right)
    {
        return Math.abs(left - right) <= MAX_CONSECUTIVE_GAP_SECONDS;
    }
}

package com.birdhouse.tracker;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;

/** Builds deterministic rolling groups from chronologically sorted planting cycles. */
final class BirdhousePlantingGrouper
{
    private BirdhousePlantingGrouper()
    {
    }

    static List<List<BirdhouseTimer>> group(List<BirdhouseTimer> timers)
    {
        if (timers == null || timers.isEmpty())
        {
            return Collections.emptyList();
        }

        List<BirdhouseTimer> sorted = new ArrayList<>(timers);
        sorted.sort(Comparator.comparingLong((BirdhouseTimer timer) -> timer.plantedAt)
            .thenComparingInt(timer -> timer.site.varp));

        List<List<BirdhouseTimer>> groups = new ArrayList<>();
        List<BirdhouseTimer> current = new ArrayList<>();
        long previousPlanting = Long.MIN_VALUE;
        for (BirdhouseTimer timer : sorted)
        {
            if (!current.isEmpty()
                && !BirdhousePlantingGroup.cyclesAreAdjacent(previousPlanting, timer.plantedAt))
            {
                groups.add(Collections.unmodifiableList(current));
                current = new ArrayList<>();
            }
            current.add(timer);
            previousPlanting = timer.plantedAt;
        }
        if (!current.isEmpty())
        {
            groups.add(Collections.unmodifiableList(current));
        }
        return Collections.unmodifiableList(groups);
    }
}

